#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    int seen[256] = {0};
    int len = strlen(s);
    for (int i = 0; i < len; i++) {
        char c = tolower(s[i]);
        if (c != ' ' && c != '\n' && c != '\r' && !seen[(unsigned char)c]) {
            seen[(unsigned char)c] = 1;
            putchar(c);
        }
    }
    putchar('\n');
    return 0;
}

